package com.bank.onboarding.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "acct_gen")
    @SequenceGenerator(name = "acct_gen", sequenceName = "account_seq", allocationSize = 50)
    private Long id;              // SEQUENCE → Hibernate pre-fetches ids → can defer INSERT

    private String holderName;
    private BigDecimal balance = BigDecimal.ZERO;
    private String status = "ACTIVE";

    protected Account() { }
    public Account(String holderName) { this.holderName = holderName; }
    public Long getId() { return id; }
}
