package com.bank.onboarding.service;

import com.bank.onboarding.model.Account;
import com.bank.onboarding.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountOnboardingService {

    private final AccountRepository accountRepo;

    @Transactional
    public void onboard(List<String> holderNames) {
        for (String name : holderNames) {
            Account acct = new Account(name);  // TRANSIENT
            accountRepo.save(acct);            // → MANAGED, INSERT QUEUED (no SQL yet)
            log.info("save() returned for {} — id assigned from sequence: {}, "
                    + "but no INSERT has run yet", name, acct.getId());
        }
        log.info("Loop done. Inserts will batch-flush at commit now...");
        // When this @Transactional method returns, Hibernate flushes all queued
        // INSERTs in a single batch, then commits.
    }
}
